package com.lbos.commercecustomer.controller; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.time.OffsetDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/customers/me/wishlist-items") public class WishlistController {private final WishlistService service;public WishlistController(WishlistService s){service=s;}private <T> ApiResponse<T> ok(HttpServletRequest r,String m,T d){return ApiResponse.of(Optional.ofNullable(r.getHeader("X-Correlation-Id")).orElse("not-provided"),m,d);}@PostMapping public ResponseEntity<ApiResponse<WishlistResponse>> add(@Valid @RequestBody ReplaceWishlistProductRequest r,HttpServletRequest h){return ResponseEntity.status(201).body(ok(h,"Wishlist item added",service.add(r)));}@GetMapping("/{id}") public ApiResponse<WishlistResponse> get(@PathVariable UUID id,HttpServletRequest h){return ok(h,"Wishlist item retrieved",service.get(id));}@GetMapping public ApiResponse<PageResponse<WishlistResponse>> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,HttpServletRequest h){return ok(h,"Wishlist retrieved",service.list(page,size));}@PatchMapping("/{id}") public ApiResponse<WishlistResponse> replace(@PathVariable UUID id,@Valid @RequestBody ReplaceWishlistProductRequest r,HttpServletRequest h){return ok(h,"Wishlist item updated",service.replace(id,r));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);}@GetMapping("/summary") public ApiResponse<WishlistSummaryResponse> summary(HttpServletRequest h){return ok(h,"Wishlist summary retrieved",service.summary());}@PostMapping("/membership") public ApiResponse<Map<Long,Boolean>> membership(@RequestBody List<Long> ids,HttpServletRequest h){return ok(h,"Wishlist membership retrieved",service.membership(ids));}}